async function handleCreate(
  basePath: string,
  name: string,
  ctx: ExtensionCommandContext,
): Promise<void> {
  // Auto-commit dirty files before leaving
  // current workspace
  const commitMsg = autoCommitCurrentBranch(
    basePath, "worktree-switch", name,
  );

  // Create from the main tree
  const mainBase = originalCwd ?? basePath;
  const info = createWorktree(mainBase, name);

  // Run post-create hook -- e.g. copy .env,
  // symlink assets
  const hookError = runWorktreePostCreateHook(
    mainBase, info.path,
  );

  // Track original cwd before switching
  if (!originalCwd) originalCwd = basePath;
  process.chdir(info.path);
}

export interface WorktreeResolverDeps {
  isInAutoWorktree: (
    basePath: string,
  ) => boolean;
  getIsolationMode: () =>
    "worktree" | "branch" | "none";
  mergeMilestoneToMain: (
    basePath: string,
    milestoneId: string,
    roadmapContent: string,
  ) => { pushed: boolean };
  syncWorktreeStateBack: (
    mainBasePath: string,
    worktreePath: string,
    milestoneId: string,
  ) => { synced: string[] };
  teardownAutoWorktree: (
    basePath: string,
    milestoneId: string,
    opts?: { preserveBranch?: boolean },
  ) => void;
  createAutoWorktree: (
    basePath: string,
    milestoneId: string,
  ) => string;
  enterAutoWorktree: (
    basePath: string,
    milestoneId: string,
  ) => string;
}
